import { z } from 'zod'
import { csvArray } from '../../utils/pagination'
import { MAX_LIMIT } from '../../utils/pagination'

/**
 * Query contracts for the public catalogue.
 *
 * The filter keys and comma-delimited encoding match the storefront's own
 * src/lib/query.ts exactly, so a filtered URL generated by the website —
 * ?color=beige,ivory&material=pure-pashmina&sort=price-low — is understood
 * here without translation.
 */

export const sortKeySchema = z
  .enum(['featured', 'newest', 'price-low', 'price-high', 'best-selling'])
  .default('featured')

export const productQuerySchema = z.object({
  category: csvArray.default([]),
  color: csvArray.default([]),
  material: csvArray.default([]),
  size: csvArray.default([]),
  pattern: csvArray.default([]),
  collection: csvArray.default([]),
  availability: csvArray.default([]),

  minPrice: z.coerce.number().positive().optional(),
  maxPrice: z.coerce.number().positive().optional(),

  sort: sortKeySchema,
  q: z.string().trim().max(120).optional(),

  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(MAX_LIMIT).default(24),

  facets: z
    .union([z.boolean(), z.string()])
    .default(true)
    .transform((value) => value !== 'false' && value !== false),
})

export type ProductQueryInput = z.infer<typeof productQuerySchema>

export const slugParamSchema = z.object({
  slug: z
    .string()
    .min(1)
    .max(160)
    .regex(/^[a-z0-9-]+$/i, 'Invalid slug'),
})

export const slugsQuerySchema = z.object({
  slugs: csvArray.default([]).transform((values) => values.slice(0, 24)),
})

export const searchQuerySchema = z.object({
  q: z.string().trim().min(1).max(80),
  limit: z.coerce.number().int().min(1).max(24).default(8),
})

export const limitQuerySchema = z.object({
  limit: z.coerce.number().int().min(1).max(48).default(8),
})

export const collectionListQuerySchema = z.object({
  group: z.enum(['women', 'men', 'collections', 'gifting', 'category']).optional(),
  featured: z
    .union([z.boolean(), z.string()])
    .optional()
    .transform((value) => (value === undefined ? undefined : value === 'true' || value === true)),
  includeHidden: z
    .union([z.boolean(), z.string()])
    .default(false)
    .transform((value) => value === 'true' || value === true),
})
